 <script>
 const renderer=new THREE.WebGLRenderer({antialias:true}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; document.body.prepend(renderer.domElement);
 const scene=new THREE.Scene(); scene.background=new THREE.Color(0x090d12); scene.fog=new THREE.FogExp2(0x090d12,.025);
 const camera=new THREE.PerspectiveCamera(38,innerWidth/innerHeight,.1,150); camera.position.set(0,7.5,13.5);
-scene.add(new THREE.HemisphereLight(0x91a4b4,.8,1.1)); const moon=new THREE.DirectionalLight(0xbad1df,2.8); moon.position.set(-8,16,7); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); scene.add(moon); const rim=new THREE.DirectionalLight(0x7f1720,1.1); rim.position.set(8,5,-8); scene.add(rim);
+scene.add(new THREE.HemisphereLight(0x91a4b4,.95,1.35)); const moon=new THREE.DirectionalLight(0xc8d6df,3.5); moon.position.set(-8,16,7); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); scene.add(moon); const rim=new THREE.DirectionalLight(0xa52a30,1.35); rim.position.set(8,5,-8); scene.add(rim); const warm=new THREE.PointLight(0xd9b978,1.4,30); warm.position.set(0,5,8); scene.add(warm);
 // arena
 const ground=new THREE.Mesh(new THREE.CircleGeometry(11,64),new THREE.MeshStandardMaterial({color:0x1b201d,roughness:.9})); ground.rotation.x=-Math.PI/2; ground.receiveShadow=true; scene.add(ground);
 for(let i=0;i<64;i++){const a=i/64*Math.PI*2,r=10.5+(i%4)*.18;const rock=new THREE.Mesh(new THREE.BoxGeometry(.08,.025,.18),new THREE.MeshStandardMaterial({color:i%3?0x30342f:0x171914}));rock.position.set(Math.cos(a)*r,.02,Math.sin(a)*r);rock.rotation.y=a;scene.add(rock)}
 for(let i=-2;i<=2;i++){const line=new THREE.Mesh(new THREE.RingGeometry(6.2+i*.01,6.25+i*.01,64),new THREE.MeshBasicMaterial({color:0x9a927b,transparent:true,opacity:.18,side:THREE.DoubleSide}));line.rotation.x=-Math.PI/2;line.position.y=.015+i*.001;scene.add(line)}
